head.script:
// 테스트 설명, 유효성 값 설정
//  _2 : columnInfo 파라미터를 Column ID(문자열)로 지정하는 분리 샘플 (_1 은 Column 인덱스 지정)
scwin.tData = {
    "description" : "[gridView > M > setBlockSelect]<br/>Body Column 정보를 사용하여 특정 Column 의 blockSelect 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 blockSelect 속성을 설정하려는 Body Column 의 ID 를 설정할 수 있어야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값(true) 을 명시 설정
    par_block.setValue("2");

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  Body Column 4개(col1~col4) 를 구성하여 columnInfo 에 Column ID 문자열을 그대로 전달할 수 있도록 한다.
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] Body Column 의 ID 는 col1~col4 이며 columnInfo 에 Column ID 문자열을 그대로 전달한다.\n[절차] columnInfo(Column ID) 와 block 값을 선택하고 setBlockSelect 를 실행한다. 차단 설정 후 해당 Column 의 Cell 을 클릭해도 포커스되지 않음을 확인한다.\n[확인] Cell 클릭 시 결과창에 출력되는 포커스 행/열 위치와 클릭한 Cell 의 포커스 여부로 차단 적용 여부를 판단한다."', '', 'label1');

    // dataList 생성 + 초기값 바인딩
    //  ※ createBasicDataList 는 col1~col4 (4컬럼) 스키마만 생성한다.
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1" : "a1", "col2" : "b1", "col3" : "c1", "col4" : "d1" },
        { "col1" : "a2", "col2" : "b2", "col3" : "c2", "col4" : "d2" },
        { "col1" : "a3", "col2" : "b3", "col3" : "c3", "col4" : "d3" },
        { "col1" : "a4", "col2" : "b4", "col3" : "c4", "col4" : "d4" }
    ]);

    // target 생성 (Body Column ID 를 col1~col4 로 부여)
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" ev:oncellclick="scwin.target1_oncellclick" id="" style="width:640px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="160" inputType="text" id="hcol1" value="col1"></w2:column>';
    strTarget += '<w2:column width="160" inputType="text" id="hcol2" value="col2"></w2:column>';
    strTarget += '<w2:column width="160" inputType="text" id="hcol3" value="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="160" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="160" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="160" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// setBlockSelect 실행 : columnInfo 를 Column ID(문자열) 그대로 전달하여 해당 Column 의 blockSelect 속성을 설정
scwin.btn_setBlockSelect_onclick = function () {
    let columnInfo = par_columnInfo.getValue();
    let blockText = par_block.getText();
    let block = (blockText === "true");

    // 이전 클릭으로 남은 포커스를 정리하여 실행 후 포커스 상태를 명확히 관찰
    scwin.target1.removeFocusedCell();

    scwin.target1.setBlockSelect(columnInfo, block);

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setBlockSelect('" + columnInfo + "', " + block + ") 실행 -> 해당 Column 의 Cell 을 클릭하여 포커스 상태를 확인하세요.");
}



// Body Cell 클릭 시 발생 : 클릭 직후의 실제 포커스 상태를 실측하여 출력
scwin.target1_oncellclick = function (rowIndex, colIndex, colID) {
    let td = document.querySelector("td[id*='target1_cell_" + rowIndex + "_" + colIndex + "']");
    let cellFocused = td ? td.className.indexOf("focusedTd") > -1 : false;

    wf_body_bottom.getObj("scwin").setReturnValue(
        "클릭한 Cell [" + rowIndex + ", " + colID + "]"
        + " -> getFocusedRowIndex() : " + scwin.target1.getFocusedRowIndex()
        + " / getFocusedColumnIndex() : " + scwin.target1.getFocusedColumnIndex()
        + " / 클릭한 Cell 포커스 여부 : " + cellFocused);
}
